import sys

def fill_gaps(n, arr):
    result = [arr[0]]
    for i in range(1, n):
        diff = arr[i] - arr[i - 1]
        if diff == 1:
            result.append(arr[i])
        else:
            for j in range(diff - 1, 0, -1):
                result.append(arr[i] - j)
            result.append(arr[i])
    return result

if __name__ == "__main__":
    n = int(sys.stdin.readline().strip())
    arr = list(map(int, sys.stdin.readline().strip().split()))
    result = fill_gaps(n, arr)
    print(" ".join(map(str, result)))

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()
    S = data[0]
    T = data[1]

    # Count the number of each character in S and T
    count_S = [0] * 26
    count_T = [0] * 26
    wildcards_S = 0
    wildcards_T = 0

    for char in S:
        if char == '@':
            wildcards_S += 1
        else:
            count_S[ord(char) - ord('a')] += 1

    for char in T:
        if char == '@':
            wildcards_T += 1
        else:
            count_T[ord(char) - ord('a')] += 1

    # Check if we can match each character in S with a character in T
    for i in range(26):
