                return
        elif count_S[i] < count_T[i]:
            if wildcards_S < count_T[i] - count_S[i]:
                print("No")
                return

    # Check if we have enough wildcards
    if wildcards_S < wildcards_T:
        print("No")
    else:
        print("Yes")

