def can_win(S, T):
    # Check if the lengths of S and T are the same
    if len(S) != len(T):
        return "No"

    # Count the frequency of each character in both strings
    count_S = {}
    count_T = {}

    for char in S:
        if char == '@':
            count_S['@'] = count_S.get('@', 0) + 1
        else:
            count_S[char] = count_S.get(char, 0) + 1

    for char in T:
        if char == '@':
            count_T['@'] = count_T.get('@', 0) + 1
        else:
            count_T[char] = count_T.get(char, 0) + 1

    # Check if the frequency of each character (excluding '@') is within 1 of each other
    for char in 'abcdefghijklmnopqrstuvwxyz':
        if char in count_S and char in count_T:
            if abs(count_S[char] - count_T[char]) > 1:
                return "No"

    # Check if the total number of '@' characters is the same
    if count_S['@'] != count_T['@']:
        return "No"

    return "Yes"

