import sys
from collections import deque

def bfs(grid, start):
    H, W = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    queue = deque([(start, 0)])
    visited = [[False] * W for _ in range(H)]
    visited[start[0]][start[1]] = True
    distances = [[float('inf')] * W for _ in range(H)]
    distances[start[0]][start[1]] = 0

    while queue:
        x, y, d = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '#' and not visited[nx][ny]:
                visited[nx][ny] = True
                distances[nx][ny] = d + 1
                queue.append((nx, ny, d + 1))

    return distances

def dp(grid, start, goal, candies):
    H, W = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    dp = [[float('inf')] * (1 << len(candies)) for _ in range(len(candies))]
    dp[0][0] = 0

    for mask in range(1 << len(candies)):
        for i in range(len(candies)):
            if mask & (1 << i):
                for dx, dy in directions:
                    nx, ny = candies[i][0] + dx, candies[i][1] + dy
                    if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '#':
                        new_mask = mask ^ (1 << i)
                        dp[i][mask] = min(dp[i][mask], dp[new_mask][mask ^ (1 << i)] + 1)

    max_candies = 0
    for mask in range(1 << len(candies)):
        if dp[mask][mask] + distances[candies[mask].x][candies[mask].y] <= T:
            max_candies = max(max_candies, bin(mask).count('1'))

    return max_candies if max_candies > 0 else -1

