import sys

def find_snake(grid):
    H, W = map(int, input().split())
    grid = [list(row) for row in sys.stdin.read().splitlines()]

    directions = [
        (0, 1), (1, 0), (0, -1), (-1, 0),  # right, down, left, up
        (1, 1), (1, -1), (-1, 1), (-1, -1)  # diagonal
    ]

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 's':
                for dr, dc in directions:
                    x, y = r, c
                    found = True
                    for _ in range(4):
                        x += dr
                        y += dc
                        if not (0 <= x < H and 0 <= y < W):
                            found = False
                            break
                        if grid[x][y] != chr(ord('n') + _):
                            found = False
                            break
                    if found:
                        return [(r+1, c+1), (x+1, y+1), (x+dr+1, y+dc+1), (x+2*dr+1, y+2*dc+1), (x+3*dr+1, y+3*dc+1)]

    return []

snake_positions = find_snake(sys.stdin.read())
for pos in snake_positions:
