from sys import stdin, stdout

def main():
    N, Q = map(int, stdin.readline().split())
    adj = [set() for _ in range(N + 1)]
    empty_count = 0

    def process_query(query):
        nonlocal empty_count
        if query[0] == 1:
            u, v = query[1], query[2]
            if not adj[u]:
                empty_count -= 1
            if not adj[v]:
                empty_count -= 1
            adj[u].add(v)
            adj[v].add(u)
        else:
            v = query[1]
            for w in adj[v]:
                adj[w].remove(v)
                if not adj[w]:
                    empty_count += 1
            if adj[v]:
                adj[v].clear()
                empty_count += 1

    output_lines = []
    for _ in range(Q):
        query = list(map(int, stdin.readline().split()))
        process_query(query)
        output_lines.append(empty_count)

    stdout.write('\n'.join(map(str, output_lines)))

if __name__ == "__main__":
