from collections import defaultdict

def merge_sets(N, M, sets):
    # Initialize a dictionary to store sets by their smallest element
    set_by_smallest = defaultdict(list)

    # Populate the dictionary with sets
    for i, (size, elements) in enumerate(sets):
        for element in elements:
            set_by_smallest[element].append((i, size))

    # Sort the sets by their smallest element
    for key in set_by_smallest:
        set_by_smallest[key].sort(key=lambda x: x[1])

    # Initialize variables to track the smallest and largest elements
    smallest = float('inf')
    largest = float('-inf')

    # Iterate through the sorted sets to find the smallest and largest elements
    for key in set_by_smallest:
        if key < smallest:
            smallest = key
        if key > largest:
            largest = key

    # Check if the smallest or largest element is already in a single set
    for key in set_by_smallest:
        if len(set_by_smallest[key]) == 1:
            if key == smallest or key == largest:
                return 0

    # Initialize variables for the minimum operations and the current set
    min_operations = 0
    current_set = None

    # Merge sets until the smallest or largest element is in a single set
    while smallest not in set_by_smallest[current_set] or largest not in set_by_smallest[current_set]:
        # Find the set with the smallest element
        for key in set_by_smallest:
            if key < smallest:
                smallest = key
                break

        # Find the set with the largest element
        for key in set_by_smallest:
            if key > largest:
                largest = key
                break

        # Merge the sets containing the smallest and largest elements
        for i, size in set_by_smallest[smallest]:
            for j, size2 in set_by_smallest[largest]:
                if i != j:
                    current_set = i
                    set_by_smallest[i].extend(set_by_smallest[j])
                    del set_by_smallest[j]
                    min_operations += 1
