            if current_set is not None:
                break

    # Check if the smallest or largest element is still in a single set
    for key in set_by_smallest:
        if len(set_by_smallest[key]) == 1:
            if key == smallest or key == largest:
                return min_operations

    # If no such set exists, return -1
    return -1

