import sys

def min_time_to_transform(S):
    X, Y, Z = map(int, sys.stdin.readline().split())
    n = len(S)

    # Initialize the list to store the characters on the screen
    screen = []
    # Initialize the Caps Lock state
    caps_lock_on = False

    # Iterate over each character in the target string
    for char in S:
        if char == 'A':
            # If the Caps Lock key is on, append 'a'
            if caps_lock_on:
                screen.append('a')
            else:
                screen.append('A')
        else:
            # If the Caps Lock key is on, append 'A'
            if caps_lock_on:
                screen.append('A')
            else:
                screen.append('a')

        # Update the Caps Lock state based on the current character
        if char == 'A':
            caps_lock_on = not caps_lock_on

    # Calculate the total time spent
    total_time = 0
    for i in range(n):
        if screen[i] != S[i]:
            # If the character on the screen does not match the target character
            # We need to press the 'a' key or the Shift key
            if screen[i] == 'A':
                # If the Caps Lock key is on, we need to press the Shift key
                if caps_lock_on:
                    total_time += Y
                else:
                    total_time += X
            else:
                # If the Caps Lock key is off, we need to press the 'a' key
                if caps_lock_on:
                    total_time += X
                else:
                    total_time += Y

    return total_time

# Read input and print the result
print(min_time_to_transform(sys.stdin.read()))

