import sys
from collections import deque

def bfs(start, N, D):
    # Initialize the queue with the starting person
    queue = deque([start])
    # Set to keep track of infected people
    infected = {start}

    while queue:
        current = queue.popleft()

        # Check all other people
        for i in range(1, N + 1):
            if i != current:
                # Calculate the Euclidean distance
                dx = abs(X[i] - X[current])
                dy = abs(Y[i] - Y[current])
                distance = (dx**2 + dy**2)**0.5

                # If the distance is less than or equal to D, mark the person as infected
                if distance <= D:
                    if i not in infected:
                        infected.add(i)
                        queue.append(i)

    return infected

