import sys
from typing import List

def build_segment_tree(arr: List[int], tree: List[int], start: int, end: int, index: int) -> None:
    if start == end:
        tree[index] = arr[start]
        return
    mid = (start + end) // 2
    build_segment_tree(arr, tree, start, mid, 2 * index + 1)
    build_segment_tree(arr, tree, mid + 1, end, 2 * index + 2)
    tree[index] = tree[2 * index + 1] + tree[2 * index + 2]

def update_segment_tree(tree: List[int], start: int, end: int, index: int, left: int, right: int, value: int) -> None:
    if left > end or right < start:
        return
    if start >= left and end <= right:
        tree[index] += value
        return
    mid = (start + end) // 2
    update_segment_tree(tree, start, mid, 2 * index + 1, left, right, value)
    update_segment_tree(tree, mid + 1, end, 2 * index + 2, left, right, value)
    tree[index] = tree[2 * index + 1] + tree[2 * index + 2]

def query_segment_tree(tree: List[int], start: int, end: int, index: int, left: int, right: int) -> int:
    if left > end or right < start:
        return 0
    if start >= left and end <= right:
        return tree[index]
    mid = (start + end) // 2
    return query_segment_tree(tree, start, mid, 2 * index + 1, left, right) + query_segment_tree(tree, mid + 1, end, 2 * index + 2, left, right)

def main():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    A = list(map(int, data[1:N+1]))
    Q = int(data[N+1])

    # Build the segment tree
    tree = [0] * (4 * N)
    build_segment_tree(A, tree, 0, N - 1, 0)

    for _ in range(Q):
        l, r = map(int, data[N+2+2*_ : N+2+2*_+2])
        if l > r:
            print(0)
            continue
        # Find the range of sleep sessions that overlap with the query range
        left = 0
        right = N - 1
        while left < right:
            mid = (left + right) // 2
            if A[mid] < l:
                left = mid + 1
            else:
                right = mid
        if A[left] < l:
            left += 1
        if A[left] > r:
            continue
        # Calculate the total sleep time for the overlapping sleep sessions
        total_sleep_time = 0
        for i in range(left, min(left + N // 2, N)):
            total_sleep_time += A[i + 1] - A[i]
        print(total_sleep_time)

if __name__ == "__main__":
    main()

