import sys
from collections import defaultdict

def read_int():
    return int(sys.stdin.readline())

def read_ints():
    return list(map(int, sys.stdin.readline().split()))

def read_line():
    return sys.stdin.readline().strip()

def read_matrix(rows):
    return [read_ints() for _ in range(rows)]

def write_int(x):
    sys.stdout.write(str(x))
    sys.stdout.write('\n')

def write_line(x):
    sys.stdout.write(str(x))
    sys.stdout.write('\n')

def fenwick_tree(n):
    return [0] * (n + 1)

def update(tree, index, value):
    while index <= len(tree) - 1:
        tree[index] += value
        index += index & -index

def query(tree, index):
    result = 0
    while index > 0:
        result += tree[index]
        index -= index & -index
    return result

def find_kth_largest(tree, n, k):
    left = 0
    right = n
    while left < right:
        mid = (left + right) // 2
        if query(tree, mid) >= k:
            right = mid
        else:
            left = mid + 1
    return left

def main():
    N, K, Q = read_ints()
    A = [0] * N
    rank_to_value = defaultdict(lambda: -1)
    value_to_rank = {}
    rank = 1
    for i in range(N):
        value = A[i]
        if value not in value_to_rank:
            value_to_rank[value] = rank
            rank_to_value[rank] = value
            rank += 1
        A[i] = value_to_rank[value]

    tree = fenwick_tree(rank)
    for i in range(N):
        update(tree, A[i], 1)

    for _ in range(Q):
        X, Y = read_ints()
        X -= 1
        old_value = A[X]
        new_value = Y
        if new_value not in value_to_rank:
            value_to_rank[new_value] = rank
            rank_to_value[rank] = new_value
            rank += 1
        A[X] = value_to_rank[new_value]

        update(tree, old_value, -1)
        update(tree, new_value, 1)

        kth_largest = find_kth_largest(tree, rank, K)
        count_greater_than_kth = rank - query(tree, kth_largest)
        result = query(tree, kth_largest) + kth_largest * (K - count_greater_than_kth)
        write_int(result)

if __name__ == "__main__":
    main()

import sys

def read_input():
    H_A, W_A = map(int, input().split())
    A = [input() for _ in range(H_A)]
    H_B, W_B = map(int, input().split())
    B = [input() for _ in range(H_B)]
    H_X, W_X = map(int, input().split())
    X = [input() for _ in range(H_X)]
    return H_A, W_A, A, H_B, W_B, B, H_X, W_X, X

def get_black_cells(sheet):
    black_cells = []
    for i in range(len(sheet)):
        for j in range(len(sheet[i])):
            if sheet[i][j] == '#':
                black_cells.append((i, j))
    return black_cells

def shift_black_cells(black_cells, dx, dy):
    return [(x + dx, y + dy) for x, y in black_cells]

def check_conditions(A, B, X):
    H_A, W_A, H_B, W_B, H_X, W_X = len(A), len(A[0]), len(B), len(B[0]), len(X), len(X[0])

    # Get black cells for A, B, and X
    black_A = get_black_cells(A)
    black_B = get_black_cells(B)
    black_X = get_black_cells(X)

    # Check if A and B can fit within X
    if max(black_A, key=lambda x: x[0])[0] >= H_X or max(black_A, key=lambda x: x[1])[1] >= W_X or \
       max(black_B, key=lambda x: x[0])[0] >= H_X or max(black_B, key=lambda x: x[1])[1] >= W_X:
        return False

    # Try all possible placements of A and B
    for dx in range(-H_X + 1, H_A + 1):
        for dy in range(-W_X + 1, W_A + 1):
            shifted_A = shift_black_cells(black_A, dx, dy)
            for dx2 in range(-H_X + 1, H_B + 1):
                for dy2 in range(-W_X + 1, W_B + 1):
                    shifted_B = shift_black_cells(black_B, dx2, dy2)
                    covered_cells = set(shifted_A).union(set(shifted_B))
                    if covered_cells == set(black_X):
                        return True
    return False

def main():
    H_A, W_A, A, H_B, W_B, B, H_X, W_X, X = read_input()
    if check_conditions(A, B, X):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    main()

