    black_squares_B = set()

    for i in range(H_A):
        for j in range(W_A):
            if A[i][j] == '#':
                black_squares_A.add((i, j))

    for i in range(H_B):
        for j in range(W_B):
            if B[i][j] == '#':
                black_squares_B.add((i, j))

