def dfs(x, y, path):
    global H, W, S, found
    if x == H and y == W:
        if path[-1] == 's':
            found = True
        return

    # Check if the current cell's letter matches the next letter in the sequence
    if path[-1] != 's' and path[-1] != S[x][y]:
        return

    # Mark the current cell as visited
    S[x][y] = '#'

    # Explore adjacent cells
    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nx, ny = x + dx, y + dy
        if 0 <= nx < H and 0 <= ny < W and S[nx][ny] != '#':
            dfs(nx, ny, path + S[nx][ny])

    # Unmark the current cell after exploring its neighbors
    S[x][y] = S[x][y].lower()

